#include <rz_util.h>
#include "minunit.h"

typedef RzFloat *(*FloatUnop)(RzFloat *x, RzFloatRMode mode);
typedef RzFloat *(*FloatBinop)(RzFloat *x, RzFloat *y, RzFloatRMode mode);
typedef RzFloat *(*FloatIntop)(RzFloat *x, RzBitVector *n, RzFloatRMode mode);

typedef struct {
	const char *name;
	FloatUnop unop;
	FloatBinop binop;
	FloatIntop intop;
} TransOp;

#define UNOP(n)  { #n, rz_float_##n, NULL, NULL }
#define BINOP(n) { #n, NULL, rz_float_##n, NULL }
#define INTOP(n) { #n, NULL, NULL, rz_float_##n }

