typedef struct {
	const char *fn;
	RzFloatFormat format;
	RzFloatRMode mode;
	const char *x; ///< operand bits, hex
	const char *y; ///< second operand bits (hex), or the integer operand (decimal, 64-bit)
	const char *expect; ///< result bits, hex
	ut32 exceptions;
} TransVector;

